public void enter()
{
    next enter();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormDataSource RetailPeriodicDiscount_ds = element.dataSource(formDataSourceStr(RetailPeriodicDiscount, RetailPeriodicDiscount)) as FormDataSource;
        RetailPeriodicDiscount retailPeriodicDiscount= RetailPeriodicDiscount_ds.cursor();

        if (retailPeriodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion)
        {
            //Hide the enum value if global unified pricing is not enabled and PeriodicDiscountType is promotion
            this.delete(enum2Str(RetailDiscountOfferLineDiscMethodBase::Price));
        }
    }
}
